INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','clefts-emphasis','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"clefts-emphasis","title":"Cleft sentences and emphatic do","level":"C1","order":63,"summary":"Focus the reader’s attention on a participant, an action or a correction.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["It-clefts","What-clefts","Emphatic do","Choose emphasis for a reason"],"rules":[{"title":"It-clefts","explanation":"An it-cleft divides a message into a focused part and a following clause: **It was X who/that ...**. The focus can be a person, thing, time or place. Use a form that makes the intended contrast clear.","pattern":"**It was the guide who** called.","commonMistakes":["It in an it-cleft is a grammatical device; it does not refer back to a thing."],"examples":["Correct the claim that she never does the task: “She does **prepare** the visitor guide!”","Correct the claim that she never does the task: “She does **restore** the old portrait!”"],"skill":"form"},{"title":"What-clefts","explanation":"A what-clause can introduce the part of the message already under discussion, followed by be and the focus. What I need is a break focuses on a break. After what + do, the focused action commonly uses a base infinitive, with to also possible in many contexts.","pattern":"**What I need is** more time. / **What she did was (to) call**.","commonMistakes":["Do not reject the to variant after what she did was merely because a bare infinitive is also possible."],"examples":["Correct a denial about yesterday: “We did **prepare** the visitor guide!”","Correct a denial about yesterday: “We did **restore** the old portrait!”"],"skill":"meaning"},{"title":"Emphatic do","explanation":"Use do, does or did in an affirmative clause to contradict a negative assumption or add emphasis. The auxiliary carries tense and agreement, so the main verb uses its base form. Spoken stress falls on the auxiliary.","pattern":"She **does know**. / We **did call**.","commonMistakes":["She does knows marks agreement twice; use does know."],"examples":["Focus on the person: “It was the assistant **who** prepared the visitor guide.”","Focus on the person: “It was the assistant **who** restored the old portrait.”"],"skill":"contrast"},{"title":"Choose emphasis for a reason","explanation":"Clefts and emphatic auxiliaries make information prominent. Too many in a paragraph can make prose heavy. Choose the structure according to what the listener already knows and which contrast matters. Written emphasis should still leave the underlying grammar clear.","pattern":"It was **yesterday** that we called.","commonMistakes":["Clefts are not needed simply to make every sentence sound more advanced."],"examples":["Complete the what-cleft: “What I need **is** time to prepare the visitor guide.”","Complete the what-cleft: “What I need **is** time to restore the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-emphasis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Focus the reader’s attention on a participant, an action or a correction.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"It-clefts","explanation":"An it-cleft divides a message into a focused part and a following clause: **It was X who/that ...**. The focus can be a person, thing, time or place. Use a form that makes the intended contrast clear.","pattern":"**It was the guide who** called.","commonMistakes":["It in an it-cleft is a grammatical device; it does not refer back to a thing."],"examples":["Correct the claim that she never does the task: “She does **prepare** the visitor guide!”","Correct the claim that she never does the task: “She does **restore** the old portrait!”"],"skill":"form","id":"clefts-emphasis-foundation-1","domain":"information","referenceIds":["bc-emphasis"],"readingVersion":"core-2026-09-v3"},{"title":"What-clefts","explanation":"A what-clause can introduce the part of the message already under discussion, followed by be and the focus. What I need is a break focuses on a break. After what + do, the focused action commonly uses a base infinitive, with to also possible in many contexts.","pattern":"**What I need is** more time. / **What she did was (to) call**.","commonMistakes":["Do not reject the to variant after what she did was merely because a bare infinitive is also possible."],"examples":["Correct a denial about yesterday: “We did **prepare** the visitor guide!”","Correct a denial about yesterday: “We did **restore** the old portrait!”"],"skill":"meaning","id":"clefts-emphasis-foundation-2","domain":"information","referenceIds":["bc-emphasis"],"readingVersion":"core-2026-09-v3"},{"title":"Emphatic do","explanation":"Use do, does or did in an affirmative clause to contradict a negative assumption or add emphasis. The auxiliary carries tense and agreement, so the main verb uses its base form. Spoken stress falls on the auxiliary.","pattern":"She **does know**. / We **did call**.","commonMistakes":["She does knows marks agreement twice; use does know."],"examples":["Focus on the person: “It was the assistant **who** prepared the visitor guide.”","Focus on the person: “It was the assistant **who** restored the old portrait.”"],"skill":"contrast","id":"clefts-emphasis-foundation-3","domain":"information","referenceIds":["bc-emphasis"],"readingVersion":"core-2026-09-v3"},{"title":"Choose emphasis for a reason","explanation":"Clefts and emphatic auxiliaries make information prominent. Too many in a paragraph can make prose heavy. Choose the structure according to what the listener already knows and which contrast matters. Written emphasis should still leave the underlying grammar clear.","pattern":"It was **yesterday** that we called.","commonMistakes":["Clefts are not needed simply to make every sentence sound more advanced."],"examples":["Complete the what-cleft: “What I need **is** time to prepare the visitor guide.”","Complete the what-cleft: “What I need **is** time to restore the old portrait.”"],"skill":"application","id":"clefts-emphasis-foundation-4","domain":"information","referenceIds":["bc-emphasis"],"readingVersion":"core-2026-09-v3"},{"domain":"information","id":"fronting-and-end-focus","title":"Fronting, end focus and end weight","explanation":"English commonly begins with an established topic and places important new information later. A writer may front an object or adjunct to create a contrast or a frame. Long or complex phrases often work well near the end. These tendencies guide information flow, but they do not license arbitrary word order.","pattern":"**That book**, I enjoyed.","examples":["**In the next room**, a meeting was taking place.","She explained to us **why the entire system had failed**."],"commonMistakes":["Fronting an object does not automatically require auxiliary inversion. Contrast That book I enjoyed with Never have I enjoyed a book so much."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"information","id":"cleft-range","title":"It-clefts, what-clefts and reversed clefts","explanation":"Cleft constructions divide a message to highlight one part. An it-cleft focuses an expression after be and follows it with a clause. A what-cleft starts with a fused relative; reversing the order can change the focus. The highlighted part may be a person, thing, time, place or reason.","pattern":"**It was on Monday that** she called.","examples":["**What I need is a break**.","**A break is what I need**."],"commonMistakes":["A cleft does not automatically contrast two named alternatives. Context may supply a correction, a new identification or an emphatic answer."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**It was the guide who** called.","**What I need is** more time. / **What she did was (to) call**.","She **does know**. / We **did call**.","It was **yesterday** that we called."],"readingVersion":"core-2026-09-v4"},"stage":"6 · Advanced control","prerequisites":["inversion"],"readingReferenceIds":["bc-emphasis","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='clefts-emphasis'
